/** Load optional renderer chunks before a runtime reports ready, keeping later R evaluation offline. */
export async function preloadBaseRuntimeAssets(): Promise<void> {
  await Promise.all([
    filledContourAsset,
    noncentralStudentTAsset,
    md5Asset,
    import("./pdf-device.js"),
    import("./png-device.js"),
    import("./postscript-device.js"),
    import("./svg-device.js"),
    import("./tiff-device.js"),
  ]);
}

