export const baseBuiltins: readonly BuiltinDefinition[] = Object.freeze(
  builtinDefinitions.map((definition) => {
    const packageName = coreBuiltinPackageName(definition.package, definition.name);
    if (packageName === definition.package) return definition;
    return {
      ...definition,
      package: packageName,
    };
  }),
);

const OPTIONS_STATE_KEY = "base.options";

/** Install the session-owned locked .Options binding and its mutable options state. */
export function initializeBaseEnvironment(
  environment: REnvironment,
  state: Map<string, unknown>,
): void {
  const options = createDefaultOptionsState();
  state.set(OPTIONS_STATE_KEY, options);
  const validateSlotReplacement: S4SlotReplacementValidator = (object, name, value, operator) => {
    const definitions = state.get(S4_CLASSES_STATE_KEY);
    validateS4SlotReplacement(
      object,
      name,
      value,
      definitions instanceof Map
        ? (definitions as ReadonlyMap<string, S4ClassDefinition>)
        : new Map<string, S4ClassDefinition>(),
      operator,
    );
  };
  state.set(S4_SLOT_REPLACEMENT_VALIDATOR_STATE_KEY, validateSlotReplacement);
  syncOptionsBinding(environment, options);
  environment.lockedBindings.add("R_compiled_by");
  environment.lockedBindings.add("extSoftVersion");
  environment.lockedBindings.add("La_version");
  environment.lockedBindings.add("La_library");
  environment.lockedBindings.add("pcre_config");
}
