const STANDARD_S4_GENERIC_PACKAGE_OWNERS = new Map<string, string>([["AIC", "stats"]]);

function standardS4GenericPackageName(name: string): string | undefined {
  const explicit = STANDARD_S4_GENERIC_PACKAGE_OWNERS.get(name);
  if (explicit !== undefined) return explicit;
  const discovered = coreBuiltinPackageName("base", name);
  return discovered === "base" ? undefined : discovered;
}

