async function builtinArithmeticOperator(
  invocation: BuiltinInvocation,
  operator: string,
): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length === 1) {
    const dispatched = await dispatchOperatorS3(invocation, operator, values);
    if (dispatched !== undefined) return dispatched;
    return jsReferenceOperators.unary(invocation.context, operator, values[0] ?? R_NULL);
  }
  if (values.length === 2) {
    const dispatched = await dispatchOperatorS3(invocation, operator, values);
    if (dispatched !== undefined) return dispatched;
    return jsReferenceOperators.binary(
      invocation.context,
      operator,
      values[0] ?? R_NULL,
      values[1] ?? R_NULL,
    );
  }
  throw new REvaluationError("NRE2140", `Operator '${operator}' requires one or two arguments.`);
}

async function builtinUnaryOperator(
  invocation: BuiltinInvocation,
  operator: string,
): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length !== 1) {
    throw new REvaluationError("NRE2140", `Operator '${operator}' requires one argument.`);
  }
  const dispatched = await dispatchOperatorS3(invocation, operator, values);
  if (dispatched !== undefined) return dispatched;
  if (operator === "!" && isHexmodeValue(values[0] ?? R_NULL)) {
    return notHexmodeValue(values[0] ?? R_NULL, invocation.context);
  }
  const input = values[0] ?? R_NULL;
  const result = jsReferenceOperators.unary(invocation.context, operator, input);
  return isVector(input) && input.s4 === true && isVector(result)
    ? { ...result, s4: true }
    : result;
}

async function builtinBinaryOperator(
  invocation: BuiltinInvocation,
  operator: string,
): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length !== 2) {
    throw new REvaluationError("NRE2140", `Operator '${operator}' requires two arguments.`);
  }
  const dispatched = await dispatchOperatorS3(invocation, operator, values);
  if (dispatched !== undefined) return dispatched;
  if (
    (operator === "&" || operator === "|") &&
    (isHexmodeValue(values[0] ?? R_NULL) || isHexmodeValue(values[1] ?? R_NULL))
  ) {
    return bitwiseHexmodeValues(
      values[0] ?? R_NULL,
      values[1] ?? R_NULL,
      operator,
      invocation.context,
    );
  }
  if (
    ["<", "<=", ">", ">=", "==", "!="].includes(operator) &&
    (isNumericVersionValue(values[0] ?? R_NULL) || isNumericVersionValue(values[1] ?? R_NULL))
  ) {
    return compareNumericVersionOperands(
      values[0] ?? R_NULL,
      values[1] ?? R_NULL,
      operator,
      invocation,
    );
  }
  return jsReferenceOperators.binary(
    invocation.context,
    operator,
    values[0] ?? R_NULL,
    values[1] ?? R_NULL,
  );
}

async function builtinMatrixProduct(invocation: BuiltinInvocation): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length !== 2) {
    throw new REvaluationError("NRE2140", "Operator '%*%' requires two arguments.");
  }
  const dispatched = await dispatchOperatorS3(invocation, "%*%", values);
  if (dispatched !== undefined) return dispatched;

  const left = requireNumeric(values[0] ?? R_NULL, "%*%");
  const right = requireNumeric(values[1] ?? R_NULL, "%*%");
  return numericMatrixProduct(invocation, left, right, "none");
}

async function builtinCrossprod(invocation: BuiltinInvocation): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length < 1 || values.length > 2) {
    throw new REvaluationError("NRE2140", "crossprod() requires one or two arguments.");
  }
  const left = requireNumeric(values[0] ?? R_NULL, "crossprod");
  const right = requireNumeric(values[1] ?? left, "crossprod");
  return numericMatrixProduct(invocation, left, right, "left");
}

async function builtinTcrossprod(invocation: BuiltinInvocation): Promise<RValue> {
  const values = await forceAll(invocation);
  if (values.length < 1 || values.length > 2) {
    throw new REvaluationError("NRE2140", "tcrossprod() requires one or two arguments.");
  }
  const left = requireNumeric(values[0] ?? R_NULL, "tcrossprod");
  const right = requireNumeric(values[1] ?? left, "tcrossprod");
  return numericMatrixProduct(invocation, left, right, "right");
}

async function builtinKronecker(
  invocation: BuiltinInvocation,
  operatorForm: boolean,
): Promise<RValue> {
  const matched = await matchExact(
    invocation,
    operatorForm ? ["X", "Y"] : ["X", "Y", "FUN", "make.dimnames", "..."],
  );
  const left = requireNumeric(required(matched, "X", operatorForm ? "%x%" : "kronecker"), "%x%");
  const right = requireNumeric(required(matched, "Y", operatorForm ? "%x%" : "kronecker"), "%x%");
  if (!operatorForm) {
    const fun = matched.get("FUN");
    if (fun !== undefined && !(fun.type === "builtin" && fun.definition.name === "*")) {
      throw new RUnsupportedFeatureError(
        "NRU6151",
        "kronecker() currently requires the default multiplication function.",
      );
    }
  }
  const makeDimensionNames = operatorForm
    ? false
    : logicalFlag(matched.get("make.dimnames"), false, "make.dimnames");
  const leftOriginalDimensions = vectorDimensions(left);
  const rightOriginalDimensions = vectorDimensions(right);
  const rank = Math.max(leftOriginalDimensions?.length ?? 1, rightOriginalDimensions?.length ?? 1);
  const leftDimensions = kroneckerDimensions(left, rank);
  const rightDimensions = kroneckerDimensions(right, rank);
  const outputDimensions: number[] = [];
  let outputLength = 1;
  for (let dimension = 0; dimension < rank; dimension += 1) {
    const extent = (leftDimensions[dimension] ?? 1) * (rightDimensions[dimension] ?? 1);
    if (
      !Number.isSafeInteger(extent) ||
      (extent !== 0 && outputLength > Number.MAX_SAFE_INTEGER / extent)
    ) {
      throw new RResourceLimitError("NRL4009", "kronecker() requested an oversized array.");
    }
    outputDimensions.push(extent);
    outputLength *= extent;
  }
  invocation.context.allocate(outputLength);
  const complex = left.type === "complex" || right.type === "complex";
  const real = new Float64Array(outputLength);
  const imaginary = complex ? new Float64Array(outputLength) : undefined;
  const missing = new Uint8Array(outputLength);
  for (let outputIndex = 0; outputIndex < outputLength; outputIndex += 1) {
    invocation.context.checkpoint();
    let remainder = outputIndex;
    let leftIndex = 0;
    let rightIndex = 0;
    let leftStride = 1;
    let rightStride = 1;
    for (let dimension = 0; dimension < rank; dimension += 1) {
      const outputExtent = outputDimensions[dimension] ?? 1;
      const coordinate = outputExtent === 0 ? 0 : remainder % outputExtent;
      remainder = outputExtent === 0 ? 0 : Math.floor(remainder / outputExtent);
      const rightExtent = rightDimensions[dimension] ?? 1;
      const rightCoordinate = coordinate % rightExtent;
      const leftCoordinate = Math.floor(coordinate / rightExtent);
      leftIndex += leftCoordinate * leftStride;
      rightIndex += rightCoordinate * rightStride;
      leftStride *= leftDimensions[dimension] ?? 1;
      rightStride *= rightExtent;
    }
    if (isMissing(left, leftIndex) || isMissing(right, rightIndex)) {
      missing[outputIndex] = 1;
      continue;
    }
    if (complex) {
      const leftValue = complexAt(left, leftIndex);
      const rightValue = complexAt(right, rightIndex);
      real[outputIndex] =
        leftValue.real * rightValue.real - leftValue.imaginary * rightValue.imaginary;
      (imaginary ?? new Float64Array())[outputIndex] =
        leftValue.real * rightValue.imaginary + leftValue.imaginary * rightValue.real;
    } else {
      real[outputIndex] = numberAt(left, leftIndex) * numberAt(right, rightIndex);
    }
  }
  let output: RVector = withDimensions(
    complex
      ? complexVector(real, imaginary ?? new Float64Array(outputLength), compactMask(missing))
      : doubleVector(real, compactMask(missing)),
    outputDimensions,
  );
  if (makeDimensionNames) {
    const dimensionNames: RValue[] = [];
    let anyNames = false;
    for (let dimension = 0; dimension < rank; dimension += 1) {
      const leftNames = kroneckerDimensionNames(left, leftOriginalDimensions, dimension);
      const rightNames = kroneckerDimensionNames(right, rightOriginalDimensions, dimension);
      if (leftNames === undefined && rightNames === undefined) {
        dimensionNames.push(R_NULL);
        continue;
      }
      anyNames = true;
      const names: string[] = [];
      const leftExtent = leftDimensions[dimension] ?? 1;
      const rightExtent = rightDimensions[dimension] ?? 1;
      for (let leftIndex = 0; leftIndex < leftExtent; leftIndex += 1) {
        for (let rightIndex = 0; rightIndex < rightExtent; rightIndex += 1) {
          names.push(`${leftNames?.[leftIndex] ?? ""}:${rightNames?.[rightIndex] ?? ""}`);
        }
      }
      dimensionNames.push(characterVector(names));
    }
    if (anyNames) output = withAttribute(output, "dimnames", listValue(dimensionNames));
  }
  return output;
}

function kroneckerDimensions(value: NumericVector, rank: number): number[] {
  const dimensions = vectorDimensions(value) ?? [value.length];
  return Array.from({ length: rank }, (_, index) => dimensions[index] ?? 1);
}

function kroneckerDimensionNames(
  value: NumericVector,
  dimensions: readonly number[] | undefined,
  dimension: number,
): readonly string[] | undefined {
  if (dimensions === undefined) return dimension === 0 ? vectorNames(value) : undefined;
  if (dimension >= dimensions.length) return undefined;
  const names = value.attributes.get("dimnames");
  if (names?.type !== "list") return undefined;
  const entry = names.values[dimension];
  return entry?.type === "character" ? entry.values : undefined;
}

function numericMatrixProduct(
  invocation: BuiltinInvocation,
  left: NumericVector,
  right: NumericVector,
  transpose: "none" | "left" | "right",
): RVector {
  const originalLeftDimensions = vectorDimensions(left);
  const originalRightDimensions = vectorDimensions(right);
  const transposeLeftMatrix = transpose === "left" && originalLeftDimensions?.length === 2;
  const transposeRightMatrix = transpose === "right" && originalRightDimensions?.length === 2;
  let leftShape = transposeLeftMatrix
    ? {
        rows: originalLeftDimensions[1] ?? 0,
        columns: originalLeftDimensions[0] ?? 0,
        matrix: true,
      }
    : transpose === "right" && originalLeftDimensions === undefined
      ? { rows: left.length, columns: 1, matrix: false }
      : matrixProductShape(left, "left");
  let rightShape = transposeRightMatrix
    ? {
        rows: originalRightDimensions[1] ?? 0,
        columns: originalRightDimensions[0] ?? 0,
        matrix: true,
      }
    : transpose === "right" && originalRightDimensions === undefined
      ? { rows: 1, columns: right.length, matrix: false }
      : matrixProductShape(right, "right");
  if (leftShape.columns !== rightShape.rows) {
    if (transpose === "none" && !leftShape.matrix && rightShape.matrix && rightShape.rows === 1) {
      leftShape = { rows: left.length, columns: 1, matrix: false };
    } else if (transpose !== "right" && !rightShape.matrix && leftShape.columns === 1) {
      rightShape = { rows: 1, columns: right.length, matrix: false };
    }
  }
  if (leftShape.columns !== rightShape.rows) {
    throw new REvaluationError("NRE2141", "non-conformable arguments");
  }

  const outputLength = leftShape.rows * rightShape.columns;
  invocation.context.allocate(outputLength);
  const complex = left.type === "complex" || right.type === "complex";
  const real = new Float64Array(outputLength);
  const imaginary = complex ? new Float64Array(outputLength) : undefined;
  const missing = new Uint8Array(outputLength);
  for (let column = 0; column < rightShape.columns; column += 1) {
    for (let row = 0; row < leftShape.rows; row += 1) {
      invocation.context.checkpoint();
      const outputIndex = row + column * leftShape.rows;
      let realTotal = 0;
      let imaginaryTotal = 0;
      for (let inner = 0; inner < leftShape.columns; inner += 1) {
        const leftIndex = transposeLeftMatrix
          ? inner + row * (originalLeftDimensions?.[0] ?? 0)
          : row + inner * leftShape.rows;
        const rightIndex = transposeRightMatrix
          ? column + inner * (originalRightDimensions?.[0] ?? 0)
          : inner + column * rightShape.rows;
        if (isMissing(left, leftIndex) || isMissing(right, rightIndex)) {
          missing[outputIndex] = 1;
          break;
        }
        if (complex) {
          const leftValue = complexAt(left, leftIndex);
          const rightValue = complexAt(right, rightIndex);
          realTotal +=
            leftValue.real * rightValue.real - leftValue.imaginary * rightValue.imaginary;
          imaginaryTotal +=
            leftValue.real * rightValue.imaginary + leftValue.imaginary * rightValue.real;
        } else {
          realTotal += numberAt(left, leftIndex) * numberAt(right, rightIndex);
        }
      }
      real[outputIndex] = realTotal;
      if (imaginary !== undefined) imaginary[outputIndex] = imaginaryTotal;
    }
  }

  let output: RVector = withDimensions(
    complex
      ? complexVector(real, imaginary ?? new Float64Array(outputLength), compactMask(missing))
      : doubleVector(real, compactMask(missing)),
    [leftShape.rows, rightShape.columns],
  );
  const rowNames = leftShape.matrix
    ? bindMatrixDimNames(left, transposeLeftMatrix ? 1 : 0)
    : transpose === "right"
      ? vectorNames(left) === undefined
        ? undefined
        : characterVector(vectorNames(left)!)
      : undefined;
  const columnNames = rightShape.matrix
    ? bindMatrixDimNames(right, transposeRightMatrix ? 0 : 1)
    : transpose === "right"
      ? vectorNames(right) === undefined
        ? undefined
        : characterVector(vectorNames(right)!)
      : undefined;
  if (rowNames !== undefined || columnNames !== undefined) {
    output = withAttribute(
      output,
      "dimnames",
      listValue([rowNames ?? R_NULL, columnNames ?? R_NULL]),
    );
  }
  return output;
}

function matrixProductShape(
  value: NumericVector,
  side: "left" | "right",
): { readonly rows: number; readonly columns: number; readonly matrix: boolean } {
  const dimensions = vectorDimensions(value);
  if (dimensions === undefined || dimensions.length === 1) {
    return side === "left"
      ? { rows: 1, columns: value.length, matrix: false }
      : { rows: value.length, columns: 1, matrix: false };
  }
  if (dimensions.length !== 2) {
    throw new RTypeMismatchError("NRT3306", "%*% requires vectors or matrices.");
  }
  return {
    rows: dimensions[0] ?? 0,
    columns: dimensions[1] ?? 0,
    matrix: true,
  };
}

async function dispatchOperatorS3(
  invocation: BuiltinInvocation,
  operator: string,
  operands: readonly RValue[],
): Promise<RValue | undefined> {
  const s4 = await dispatchOperatorS4(invocation, operator, operands);
  if (s4 !== undefined) return s4;
  for (const [index, operand] of operands.entries()) {
    if (objectClasses(operand) === undefined) continue;
    for (const generic of [operator, "Ops"]) {
      const dispatched = await invocation.dispatchS3IfPresent(
        generic,
        operand,
        invocation.arguments,
        false,
        index,
        generic === "Ops" ? operator : undefined,
        operands,
      );
      if (dispatched !== undefined) return dispatched;
    }
  }
  return undefined;
}

async function dispatchOperatorS4(
  invocation: BuiltinInvocation,
  operator: string,
  operands: readonly RValue[],
): Promise<RValue | undefined> {
  if (!operands.some((operand) => isVector(operand) && operand.s4 === true)) return undefined;
  // Primitive operators are implicit S4 generics. Preserve the concrete primitive as the
  // callGeneric() fallback, including when an Ops group method was selected.
  await ensureS4GenericFallback(operator, invocation);
  const arguments_ = operands.map((value, index) => {
    const name = invocation.arguments[index]?.name;
    return name === undefined ? { value } : { name, value };
  });
  for (const generic of [operator, "Ops"]) {
    const method = selectS4Method(generic, arguments_, invocation);
    if (method === undefined) continue;
    const stack = s4DispatchStack(invocation);
    // callGeneric() inside a group method redispatches the concrete operator, not "Ops".
    stack.push({ generic: generic === "Ops" ? operator : generic });
    try {
      const definition = stateMap<string, S4GenericDefinition>(
        invocation,
        S4_GENERICS_STATE_KEY,
      ).get(generic);
      return validateS4GenericValue(
        generic,
        await invocation.invoke(method, arguments_, invocation.currentEnvironment()),
        definition,
        invocation,
      );
    } finally {
      stack.pop();
    }
  }
  return undefined;
}

async function builtinC(invocation: BuiltinInvocation): Promise<RValue> {
  const entries: { readonly name?: string; readonly value: RValue }[] = [];
  for (const argument of invocation.arguments) {
    const value = await invocation.force(argument.promise);
    entries.push(argument.name === undefined ? { value } : { name: argument.name, value });
  }
  for (let index = 0; index < entries.length; index += 1) {
    const entry = entries[index];
    if (entry === undefined || objectClasses(entry.value) === undefined) continue;
    const dispatched = await invocation.dispatchS3IfPresent(
      "c",
      entry.value,
      invocation.arguments,
      false,
      index,
    );
    if (dispatched !== undefined) return dispatched;
  }
  if (entries.some((entry) => isNumericVersionValue(entry.value))) {
    return combineNumericVersionValues(entries, invocation);
  }
  if (entries.some((entry) => entry.value.type === "expression")) {
    return combineExpressionEntries(entries, invocation);
  }
  if (entries.some((entry) => entry.value.type !== "null" && !isAtomic(entry.value))) {
    return combineListEntries(entries, invocation);
  }
  return combineAtomicEntries(entries, invocation, "c");
}

async function builtinCombinePosixct(invocation: BuiltinInvocation): Promise<RValue> {
  const { matched, dots } = matchBuiltinArguments(invocation, ["...", "recursive"]);
  const recursive = matched.get("recursive");
  if (recursive !== undefined && !recursive.promise.missing) {
    logicalFlag(await invocation.force(recursive.promise), false, "recursive");
  }
  const entries: { readonly name?: string; readonly value: RValue }[] = [];
  for (const argument of dots) {
    const value = await invocation.force(argument.promise);
    entries.push(argument.name === undefined ? { value } : { name: argument.name, value });
  }
  const combined = combineAtomicEntries(
    entries.map((entry) => ({
      ...entry,
      value: isVector(entry.value) ? withoutClasses(entry.value) : entry.value,
    })),
    invocation,
    "c.POSIXct",
  );
  const first = entries[0]?.value;
  if (
    first === undefined ||
    !isVector(first) ||
    vectorClasses(first)?.includes("POSIXct") !== true ||
    !isAtomic(combined)
  ) {
    return combined;
  }

  let result = withClasses(combined, ["POSIXct", "POSIXt"]);
  const nonNull = entries.map((entry) => entry.value).filter((value) => value.type !== "null");
  const timezones = nonNull.map((value) => {
    if (!isVector(value) || vectorClasses(value)?.includes("POSIXct") !== true) return undefined;
    const timezone = value.attributes.get("tzone");
    return timezone?.type === "character" && timezone.length === 1 && !isMissing(timezone, 0)
      ? timezone.values[0]
      : undefined;
  });
  const timezone = timezones[0];
  if (timezone !== undefined && timezones.every((candidate) => candidate === timezone)) {
    result = withAttribute(result, "tzone", characterVector([timezone]));
  }
  return result;
}

function combineExpressionEntries(
  entries: readonly { readonly name?: string; readonly value: RValue }[],
  invocation: BuiltinInvocation,
): RExpression {
  const values: AstNode[] = [];
  const names: string[] = [];
  let hasNames = false;
  const append = (
    value: AstNode,
    outerName: string | undefined,
    innerName: string,
    index: number,
    length: number,
  ): void => {
    values.push(value);
    const name =
      outerName === undefined
        ? innerName
        : innerName.length > 0
          ? `${outerName}.${innerName}`
          : length === 1
            ? outerName
            : `${outerName}${index + 1}`;
    names.push(name);
    if (name.length > 0) hasNames = true;
  };

  for (const entry of entries) {
    invocation.context.checkpoint();
    const value = entry.value;
    if (value.type === "null") continue;
    if (value.type === "expression") {
      const namesAttribute = value.attributes?.get("names");
      const innerNames = namesAttribute?.type === "character" ? namesAttribute.values : undefined;
      for (let index = 0; index < value.values.length; index += 1) {
        append(
          value.values[index] ?? nullAst(),
          entry.name,
          innerNames?.[index] ?? "",
          index,
          value.values.length,
        );
      }
      continue;
    }
    if (value.type === "list" || value.type === "pairlist") {
      const innerNames = vectorNames(value);
      for (let index = 0; index < value.values.length; index += 1) {
        append(
          languageValueAst(value.values[index] ?? R_NULL),
          entry.name,
          innerNames?.[index] ?? "",
          index,
          value.values.length,
        );
      }
      continue;
    }
    if (isAtomic(value)) {
      const innerNames = vectorNames(value);
      for (let index = 0; index < value.length; index += 1) {
        append(
          atomicElementAst(value, index),
          entry.name,
          innerNames?.[index] ?? "",
          index,
          value.length,
        );
      }
      continue;
    }
    append(languageValueAst(value), entry.name, "", 0, 1);
  }

  invocation.context.allocate(values.length);
  return {
    type: "expression",
    values: Object.freeze(values),
    ...(hasNames
      ? { attributes: new Map<string, RValue>([["names", characterVector(names)]]) }
      : {}),
  };
}

function combineListEntries(
  entries: readonly { readonly name?: string; readonly value: RValue }[],
  invocation: BuiltinInvocation,
): RList {
  const values: RValue[] = [];
  const names: string[] = [];
  let hasNames = false;
  const append = (
    value: RValue,
    outerName: string | undefined,
    innerName: string,
    index: number,
    length: number,
  ) => {
    values.push(value);
    let name = innerName;
    if (outerName !== undefined) {
      name =
        innerName.length > 0
          ? `${outerName}.${innerName}`
          : length === 1
            ? outerName
            : `${outerName}${index + 1}`;
    }
    names.push(name);
    if (name.length > 0) hasNames = true;
  };
  for (const entry of entries) {
    invocation.context.checkpoint();
    if (entry.value.type === "null") continue;
    if (entry.value.type === "list" || entry.value.type === "pairlist") {
      const innerNames = vectorNames(entry.value);
      for (let index = 0; index < entry.value.length; index += 1) {
        append(
          entry.value.values[index] ?? R_NULL,
          entry.name,
          innerNames?.[index] ?? "",
          index,
          entry.value.length,
        );
      }
      continue;
    }
    if (isAtomic(entry.value)) {
      const innerNames = vectorNames(entry.value);
      for (let index = 0; index < entry.value.length; index += 1) {
        append(
          extractVectorElement(entry.value, integerVector([index + 1]), invocation.context),
          entry.name,
          innerNames?.[index] ?? "",
          index,
          entry.value.length,
        );
      }
      continue;
    }
    append(entry.value, entry.name, "", 0, 1);
  }
  invocation.context.allocate(values.length);
  return listValue(values, hasNames ? names : undefined);
}

function combineAtomicEntries(
  entries: readonly { readonly name?: string; readonly value: RValue }[],
  invocation: BuiltinInvocation,
  call: string,
): RValue {
  const atomicEntries = entries.filter((entry) => entry.value.type !== "null");
  if (atomicEntries.length === 0) return R_NULL;
  if (!atomicEntries.every((entry) => isAtomic(entry.value))) {
    throw new RUnsupportedFeatureError(
      "NRU6101",
      `${call}() currently combines atomic vectors only.`,
    );
  }

  const vectors = atomicEntries.map((entry) => entry.value) as AtomicVector[];
  const type = commonType(vectors);
  const length = vectors.reduce((total, vector) => total + vector.length, 0);
  const names =
    length === 0
      ? undefined
      : combinedNames(
          atomicEntries as readonly { readonly name?: string; readonly value: AtomicVector }[],
        );
  invocation.context.allocate(length);
  const mask = new Uint8Array(length);
  let offset = 0;

  if (type === "character") {
    const output: string[] = [];
    const encodings: RCharacterEncoding[] = [];
    const byteValues: Uint8Array[] = [];
    for (const vector of vectors) {
      for (let index = 0; index < vector.length; index += 1) {
        invocation.context.checkpoint();
        if (isMissing(vector, index)) mask[offset] = 1;
        output.push(stringAt(vector, index));
        encodings.push(
          vector.type === "character" ? characterEncodingAt(vector, index) : "unknown",
        );
        byteValues.push(
          vector.type === "character"
            ? characterBytesAt(vector, index)
            : encodeUtf8(stringAt(vector, index)),
        );
        offset += 1;
      }
    }
    return attachNames(characterVector(output, compactMask(mask), encodings, byteValues), names);
  }
  if (type === "double") {
    const output = new Float64Array(length);
    for (const vector of vectors) {
      for (let index = 0; index < vector.length; index += 1) {
        invocation.context.checkpoint();
        if (isMissing(vector, index)) mask[offset] = 1;
        output[offset] = numberAt(vector, index);
        offset += 1;
      }
    }
    return attachNames(doubleVector(output, compactMask(mask)), names);
  }
  if (type === "complex") {
    const real = new Float64Array(length);
    const imaginary = new Float64Array(length);
    for (const vector of vectors) {
      for (let index = 0; index < vector.length; index += 1) {
        invocation.context.checkpoint();
        if (isMissing(vector, index)) mask[offset] = 1;
        const value = complexAt(vector, index);
        real[offset] = value.real;
        imaginary[offset] = value.imaginary;
        offset += 1;
      }
    }
    return attachNames(complexVector(real, imaginary, compactMask(mask)), names);
  }
  if (type === "integer") {
    const output = new Int32Array(length);
    for (const vector of vectors) {
      for (let index = 0; index < vector.length; index += 1) {
        invocation.context.checkpoint();
        if (isMissing(vector, index)) mask[offset] = 1;
        output[offset] = numberAt(vector, index);
        offset += 1;
      }
    }
    return attachNames(integerVector(output, compactMask(mask)), names);
  }
  if (type === "raw") {
    const output = new Uint8Array(length);
    for (const vector of vectors) {
      for (let index = 0; index < vector.length; index += 1) {
        invocation.context.checkpoint();
        output[offset] = numberAt(vector, index);
        offset += 1;
      }
    }
    return attachNames(rawVector(output), names);
  }

  const output = new Uint8Array(length);
  for (const vector of vectors) {
    for (let index = 0; index < vector.length; index += 1) {
      invocation.context.checkpoint();
      if (isMissing(vector, index)) mask[offset] = 1;
      output[offset] = numberAt(vector, index) === 0 ? 0 : 1;
      offset += 1;
    }
  }
  return attachNames(logicalVector(output, compactMask(mask)), names);
}

function builtinMissing(invocation: BuiltinInvocation): RValue {
  const argument = invocation.arguments[0];
  if (argument === undefined || invocation.arguments.length !== 1) {
    throw new REvaluationError("NRE2103", "missing() requires exactly one argument name.");
  }
  const expression = argument.promise.expression;
  const name =
    expression?.kind === "Identifier"
      ? expression.name
      : expression?.kind === "UnsupportedExpression" && expression.feature === "dots"
        ? "..."
        : undefined;
  if (name === undefined) {
    throw new REvaluationError("NRE2105", "Invalid use of missing().", {
      details: {
        expression: expression === null ? null : deparseAst(expression),
        kind: expression?.kind,
      },
    });
  }
  const dotDot = /^\.\.([1-9][0-9]*)$/u.exec(name);
  let binding: RBinding | undefined;
  if (dotDot === null) {
    binding = lookupBinding(argument.promise.environment, name);
  } else {
    const dots = lookupBinding(argument.promise.environment, "...");
    if (dots?.type !== "dots") {
      throw new REvaluationError(
        "NRE2105",
        `missing(${name}) used in an incorrect context, no '...' to look in.`,
      );
    }
    binding = dots.arguments[Number(dotDot[1]) - 1]?.promise;
    if (binding === undefined) return logicalVector([true]);
  }
  if (binding === undefined) {
    throw new REvaluationError("NRE2105", `missing(${name}) did not find an argument.`);
  }
  return logicalVector([isMissingArgumentBinding(binding, new Set())]);
}

async function builtinMethodsHasArg(invocation: BuiltinInvocation): Promise<RValue> {
  const argument = invocation.arguments[0];
  if (argument === undefined || invocation.arguments.length !== 1) {
    throw new REvaluationError("NRE2103", "hasArg() requires exactly one argument name.");
  }
  const expression = argument.promise.expression;
  let name: string | undefined;
  if (expression?.kind === "Identifier") name = expression.name;
  else if (expression?.kind === "StringLiteral") name = expression.value;
  else {
    const value = await invocation.force(argument.promise);
    if (value.type === "null" || (isAtomic(value) && value.length === 0)) {
      throw new REvaluationError("NRE2105", "argument is of length zero");
    }
    if (!isAtomic(value)) return logicalVector([0]);
    const names = coerceAtomicToCharacter(value, invocation);
    if (names.length > 1) {
      throw new REvaluationError("NRE2105", "the condition has length > 1");
    }
    if (names.length === 0 || isMissing(names, 0)) return logicalVector([0]);
    name = names.values[0] ?? "";
  }

  const caller = argument.promise.environment;
  if (name === "...") {
    const dots = caller.bindings.get("...");
    return logicalVector([dots?.type === "dots" && dots.arguments.length > 0 ? 1 : 0]);
  }
  const binding = caller.bindings.get(name);
  if (binding?.type === "promise") {
    return logicalVector([isMissingArgumentBinding(binding, new Set()) ? 0 : 1]);
  }
  const dots = caller.bindings.get("...");
  return logicalVector([
    dots?.type === "dots" && dots.arguments.some((candidate) => candidate.name === name) ? 1 : 0,
  ]);
}

async function builtinStatsCheckModelFrameClasses(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["cl", "m", "ordNotOK"]);
  const expected = required(matched, "cl", ".checkMFClasses");
  const model = required(matched, "m", ".checkMFClasses");
  const orderedMismatch = logicalFlag(matched.get("ordNotOK"), false, "ordNotOK");
  if (expected.type !== "character") {
    throw new RTypeMismatchError("NRT3401", ".checkMFClasses() requires named character classes.");
  }
  if (model.type !== "list") {
    throw new RTypeMismatchError("NRT3401", ".checkMFClasses() requires a model-frame list.");
  }
  const expectedNames = vectorNames(expected);
  const modelNames = vectorNames(model);
  if (expectedNames === undefined || modelNames === undefined) {
    throw new RTypeMismatchError("NRT3401", ".checkMFClasses() requires named inputs.");
  }
  const suppliedByName = new Map<string, string>();
  for (let index = 0; index < model.values.length; index += 1) {
    const name = modelNames[index] ?? "";
    if (name !== "") suppliedByName.set(name, modelFrameValueClass(model.values[index] as RValue));
  }
  const mismatches: {
    readonly name: string;
    readonly expected: string;
    readonly supplied: string;
  }[] = [];
  for (let index = 0; index < expected.length; index += 1) {
    if (isMissing(expected, index)) continue;
    const name = expectedNames[index] ?? "";
    const supplied = suppliedByName.get(name);
    if (supplied === undefined) continue;
    let fitted = expected.values[index] ?? "";
    let observed = supplied;
    if (!orderedMismatch) {
      if (fitted === "ordered") fitted = "factor";
      if (observed === "ordered") observed = "factor";
    }
    if (observed === "ordered" && fitted === "factor") observed = "factor";
    if (observed === "factor" && fitted === "character") observed = "character";
    if (fitted !== observed) mismatches.push({ name, expected: fitted, supplied: observed });
  }
  if (mismatches.length === 1) {
    const mismatch = mismatches[0] as (typeof mismatches)[number];
    throw new REvaluationError(
      "NRE2284",
      `variable '${mismatch.name}' was fitted with type "${mismatch.expected}" but type "${mismatch.supplied}" was supplied`,
    );
  }
  if (mismatches.length > 1) {
    throw new REvaluationError(
      "NRE2284",
      `variables ${mismatches.map(({ name }) => `'${name}'`).join(", ")} were specified with different types from the fit`,
    );
  }
  invocation.setResultVisibility("invisible");
  return R_NULL;
}

function modelFrameValueClass(value: RValue): string {
  if (!isVector(value)) return "other";
  const classes = vectorClasses(value) ?? [];
  if (classes.includes("ordered")) return "ordered";
  if (classes.includes("factor")) return "factor";
  const dimensions = vectorDimensions(value);
  if (dimensions?.length === 2) {
    const numeric = value.type === "integer" || value.type === "double" || value.type === "complex";
    return `${numeric ? "n" : ""}matrix.${dimensions[1] ?? 0}`;
  }
  if (value.type === "integer" || value.type === "double") return "numeric";
  if (value.type === "logical") return "logical";
  if (value.type === "character") return "character";
  if (value.type === "complex") return "complex";
  return "other";
}

function builtinNArgs(invocation: BuiltinInvocation): RValue {
  if (invocation.arguments.length !== 0) {
    throw new REvaluationError("NRE2103", "nargs() does not accept arguments.");
  }
  const count = invocation.currentArgumentCount();
  return count === undefined ? integerVector([0], new Uint8Array([1])) : integerVector([count]);
}

function dotsBinding(invocation: BuiltinInvocation) {
  const dots = lookupBinding(invocation.currentEnvironment(), "...");
  if (dots?.type !== "dots") {
    throw new REvaluationError(
      "NRE2105",
      `incorrect context: the current call has no '...' to look in`,
    );
  }
  return dots;
}

function builtinDotsLength(invocation: BuiltinInvocation): RValue {
  if (invocation.arguments.length !== 0) {
    throw new REvaluationError("NRE2103", "...length() does not accept arguments.");
  }
  return integerVector([dotsBinding(invocation).arguments.length]);
}

function builtinDotsNames(invocation: BuiltinInvocation): RValue {
  if (invocation.arguments.length !== 0) {
    throw new REvaluationError("NRE2103", "...names() does not accept arguments.");
  }
  const arguments_ = dotsBinding(invocation).arguments;
  if (arguments_.length === 0) return R_NULL;
  invocation.context.allocate(arguments_.length);
  return characterVector(arguments_.map((argument) => argument.name ?? ""));
}

async function builtinDotsElement(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["n"]);
  const index = Math.trunc(numericScalar(required(matched, "n", "...elt"), "n"));
  const dots = dotsBinding(invocation);
  const argument = dots.arguments[index - 1];
  if (index < 1 || argument === undefined) {
    throw new REvaluationError("NRE2105", `the ... list does not contain ${index} elements`);
  }
  if (argument.promise.missing) {
    throw new REvaluationError("NRE2103", `argument ${index} is empty`);
  }
  return invocation.force(argument.promise);
}

function builtinQuote(invocation: BuiltinInvocation): RValue {
  if (invocation.arguments.length !== 1) {
    throw new REvaluationError("NRE2103", "quote() requires exactly one argument.");
  }
  const argument = invocation.arguments[0];
  if (
    argument === undefined ||
    (argument.name !== undefined && argument.name !== "expr" && !"expr".startsWith(argument.name))
  ) {
    throw new REvaluationError("NRE2101", "Unused argument in quote().");
  }
  const expression = argument.promise.expression;
  if (expression === null || argument.promise.missing) {
    return { type: "symbol", name: "" } satisfies RSymbol;
  }
  return quoteAst(expression);
}

async function builtinBrace(invocation: BuiltinInvocation): Promise<RValue> {
  let value: RValue = R_NULL;
  let visibility: "visible" | "invisible" = "invisible";
  for (const argument of invocation.arguments) {
    const result = await invocation.forceDetailed(argument.promise);
    value = result.value;
    visibility = result.visible ? "visible" : "invisible";
  }
  invocation.setResultVisibility(visibility);
  return value;
}

async function builtinFirstClassAssignment(invocation: BuiltinInvocation): Promise<RValue> {
  if (invocation.arguments.length !== 2) {
    throw new REvaluationError("NRE2103", "'<-' requires exactly two arguments.");
  }
  const targetArgument = invocation.arguments[0];
  const valueArgument = invocation.arguments[1];
  if (targetArgument === undefined || valueArgument === undefined) {
    throw new REvaluationError("NRE2103", "'<-' requires exactly two arguments.");
  }
  let targetName: string | undefined;
  if (targetArgument.promise.expression?.kind === "Identifier") {
    targetName = targetArgument.promise.expression.name;
  } else {
    const target = await invocation.force(targetArgument.promise);
    if (target.type === "symbol" && target.name.length > 0) targetName = target.name;
  }
  if (targetName === undefined) {
    throw new RTypeMismatchError(
      "NRT3207",
      "The first argument to '<-' must identify a direct binding.",
    );
  }
  const value = await invocation.force(valueArgument.promise);
  await invocation.assignBinding(invocation.currentEnvironment(), targetName, value);
  invocation.setResultVisibility("invisible");
  return value;
}

async function builtinLanguageSubstitute(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["expr", "env"]);
  const expressionArgument = matched.get("expr");
  const expression = expressionArgument?.promise.expression;
  if (
    expressionArgument === undefined ||
    expression === undefined ||
    expression === null ||
    expressionArgument.promise.missing
  ) {
    throw new REvaluationError("NRE2103", "Argument 'expr' is missing in substitute().");
  }

  let resolve: (name: string) => RBinding | undefined;
  const environmentArgument = matched.get("env");
  if (environmentArgument === undefined) {
    const environment = expressionArgument.promise.environment;
    resolve = invocation.isGlobalEnvironment(environment)
      ? () => undefined
      : (name) => environment.bindings.get(name);
  } else {
    const environment = await invocation.force(environmentArgument.promise);
    if (environment.type === "environment") {
      resolve = invocation.isGlobalEnvironment(environment)
        ? () => undefined
        : (name) => environment.bindings.get(name);
    } else if (environment.type === "list") {
      const names = vectorNames(environment);
      const values = new Map<string, RValue>();
      for (const [index, name] of (names ?? []).entries()) {
        if (name.length > 0) values.set(name, environment.values[index] ?? R_NULL);
      }
      resolve = (name) => values.get(name);
    } else {
      throw new RTypeMismatchError(
        "NRT3210",
        "substitute(env=) requires an environment, list, or data frame.",
        { details: { type: environment.type } },
      );
    }
  }

  return quoteAst(substituteAst(expression, resolve, invocation));
}

async function builtinBquote(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["expr", "where", "splice"]);
  const expressionArgument = matched.get("expr");
  if (
    expressionArgument === undefined ||
    expressionArgument.promise.missing ||
    expressionArgument.promise.expression === null
  ) {
    throw new REvaluationError("NRE2103", "Argument 'expr' is missing in bquote().");
  }
  const whereArgument = matched.get("where");
  const whereValue =
    whereArgument === undefined ? undefined : await invocation.force(whereArgument.promise);
  const where =
    whereValue === undefined
      ? invocation.currentEnvironment()
      : whereValue.type === "environment"
        ? whereValue
        : whereValue.type === "list" || whereValue.type === "pairlist"
          ? withEnvironment(whereValue, invocation.currentEnvironment())
          : undefined;
  if (where === undefined) {
    throw new RTypeMismatchError(
      "NRT3205",
      "bquote(where=) requires an environment, list, or pairlist.",
    );
  }
  const spliceArgument = matched.get("splice");
  if (
    spliceArgument !== undefined &&
    logicalFlag(await invocation.force(spliceArgument.promise), false, "splice")
  ) {
    throw new RUnsupportedFeatureError(
      "NRU6193",
      "bquote(splice = TRUE) list splicing is not yet supported.",
    );
  }
  return quoteAst(await bquoteAst(expressionArgument.promise.expression, where, invocation));
}

async function bquoteAst(
  node: AstNode,
  environment: REnvironment,
  invocation: BuiltinInvocation,
): Promise<AstNode> {
  invocation.context.checkpoint();
  if (
    node.kind === "CallExpression" &&
    node.callee.kind === "Identifier" &&
    node.callee.name === "."
  ) {
    const argument = node.arguments[0];
    if (argument === undefined || node.arguments.length !== 1 || argument.name !== undefined) {
      throw new REvaluationError("NRE2103", ".() inside bquote() requires one argument.");
    }
    const value = await invocation.evaluate(
      { type: "language", expression: argument.value },
      environment,
    );
    return embeddedCallArgumentAst(value);
  }
  switch (node.kind) {
    case "Program":
      return {
        ...node,
        body: await bquoteNodes(node.body, environment, invocation),
      };
    case "Block":
      return {
        ...node,
        body: await bquoteNodes(node.body, environment, invocation),
      };
    case "Identifier":
    case "DoubleLiteral":
    case "ComplexLiteral":
    case "IntegerLiteral":
    case "StringLiteral":
    case "LogicalLiteral":
    case "NullLiteral":
    case "MissingLiteral":
    case "BreakExpression":
    case "NextExpression":
    case "UnsupportedExpression":
      return node;
    case "UnaryExpression":
      return { ...node, operand: await bquoteAst(node.operand, environment, invocation) };
    case "BinaryExpression":
      return {
        ...node,
        left: await bquoteAst(node.left, environment, invocation),
        right: await bquoteAst(node.right, environment, invocation),
      };
    case "AssignmentExpression":
      return { ...node, value: await bquoteAst(node.value, environment, invocation) };
    case "ReplacementExpression":
      return {
        ...node,
        target: (await bquoteAst(node.target, environment, invocation)) as typeof node.target,
        value: await bquoteAst(node.value, environment, invocation),
      };
    case "CallExpression":
      return {
        ...node,
        callee: await bquoteAst(node.callee, environment, invocation),
        arguments: await bquoteArguments(node.arguments, environment, invocation),
      };
    case "FunctionExpression":
      return {
        ...node,
        parameters: await bquoteParameters(node.parameters, environment, invocation),
        body: await bquoteAst(node.body, environment, invocation),
      };
    case "IfExpression":
      return {
        ...node,
        condition: await bquoteAst(node.condition, environment, invocation),
        consequence: await bquoteAst(node.consequence, environment, invocation),
        ...(node.alternative === undefined
          ? {}
          : { alternative: await bquoteAst(node.alternative, environment, invocation) }),
      };
    case "ForExpression":
      return {
        ...node,
        variable: await bquoteAst(node.variable, environment, invocation),
        sequence: await bquoteAst(node.sequence, environment, invocation),
        body: await bquoteAst(node.body, environment, invocation),
      };
    case "WhileExpression":
      return {
        ...node,
        condition: await bquoteAst(node.condition, environment, invocation),
        body: await bquoteAst(node.body, environment, invocation),
      };
    case "RepeatExpression":
      return { ...node, body: await bquoteAst(node.body, environment, invocation) };
    case "ReturnExpression":
      return node.value === undefined
        ? node
        : { ...node, value: await bquoteAst(node.value, environment, invocation) };
    case "SubsetExpression":
      return {
        ...node,
        target: await bquoteAst(node.target, environment, invocation),
        arguments: await bquoteArguments(node.arguments, environment, invocation),
      };
    case "NamespaceExpression":
      return {
        ...node,
        namespace: await bquoteAst(node.namespace, environment, invocation),
        member: await bquoteAst(node.member, environment, invocation),
      };
    case "FormulaExpression":
      return {
        ...node,
        ...(node.left === undefined
          ? {}
          : { left: await bquoteAst(node.left, environment, invocation) }),
        right: await bquoteAst(node.right, environment, invocation),
      };
    case "PipeExpression":
      return {
        ...node,
        left: await bquoteAst(node.left, environment, invocation),
        right: await bquoteAst(node.right, environment, invocation),
      };
    case "ConstantExpression":
      return node;
    default:
      return assertNever(node);
  }
}

async function bquoteNodes(
  nodes: readonly AstNode[],
  environment: REnvironment,
  invocation: BuiltinInvocation,
): Promise<readonly AstNode[]> {
  const output: AstNode[] = [];
  for (const node of nodes) output.push(await bquoteAst(node, environment, invocation));
  return Object.freeze(output);
}

async function bquoteArguments(
  arguments_: readonly CallArgument[],
  environment: REnvironment,
  invocation: BuiltinInvocation,
): Promise<readonly CallArgument[]> {
  const output: CallArgument[] = [];
  for (const argument of arguments_) {
    output.push({
      ...argument,
      value: await bquoteAst(argument.value, environment, invocation),
    });
  }
  return Object.freeze(output);
}

async function bquoteParameters(
  parameters: readonly FunctionParameter[],
  environment: REnvironment,
  invocation: BuiltinInvocation,
): Promise<readonly FunctionParameter[]> {
  const output: FunctionParameter[] = [];
  for (const parameter of parameters) {
    output.push({
      ...parameter,
      ...(parameter.defaultValue === undefined
        ? {}
        : { defaultValue: await bquoteAst(parameter.defaultValue, environment, invocation) }),
    });
  }
  return Object.freeze(output);
}

function substituteAst(
  node: AstNode,
  resolve: (name: string) => RBinding | undefined,
  invocation: BuiltinInvocation,
): AstNode {
  invocation.context.checkpoint();
  switch (node.kind) {
    case "Program":
      return { ...node, body: node.body.map((entry) => substituteAst(entry, resolve, invocation)) };
    case "Block":
      return { ...node, body: node.body.map((entry) => substituteAst(entry, resolve, invocation)) };
    case "Identifier":
      return substituteIdentifier(node, resolve);
    case "DoubleLiteral":
    case "ComplexLiteral":
    case "IntegerLiteral":
    case "StringLiteral":
    case "LogicalLiteral":
    case "NullLiteral":
    case "MissingLiteral":
    case "BreakExpression":
    case "NextExpression":
      return node;
    case "UnaryExpression":
      return { ...node, operand: substituteAst(node.operand, resolve, invocation) };
    case "BinaryExpression":
      return {
        ...node,
        left: substituteAst(node.left, resolve, invocation),
        right: substituteAst(node.right, resolve, invocation),
      };
    case "AssignmentExpression":
      return {
        ...node,
        target: substituteAst(node.target, resolve, invocation) as typeof node.target,
        value: substituteAst(node.value, resolve, invocation),
      };
    case "ReplacementExpression": {
      const target = substituteAst(node.target, resolve, invocation);
      return {
        ...node,
        target: target as typeof node.target,
        value: substituteAst(node.value, resolve, invocation),
      };
    }
    case "CallExpression":
      return {
        ...node,
        callee: substituteAst(node.callee, resolve, invocation),
        arguments: substituteCallArguments(node.arguments, resolve, invocation),
      };
    case "FunctionExpression":
      return {
        ...node,
        parameters: node.parameters.map((parameter) => ({
          ...parameter,
          ...(parameter.defaultValue === undefined
            ? {}
            : {
                defaultValue: substituteAst(parameter.defaultValue, resolve, invocation),
              }),
        })),
        body: substituteAst(node.body, resolve, invocation),
      };
    case "IfExpression":
      return {
        ...node,
        condition: substituteAst(node.condition, resolve, invocation),
        consequence: substituteAst(node.consequence, resolve, invocation),
        ...(node.alternative === undefined
          ? {}
          : { alternative: substituteAst(node.alternative, resolve, invocation) }),
      };
    case "ForExpression":
      return {
        ...node,
        variable: substituteAst(node.variable, resolve, invocation),
        sequence: substituteAst(node.sequence, resolve, invocation),
        body: substituteAst(node.body, resolve, invocation),
      };
    case "WhileExpression":
      return {
        ...node,
        condition: substituteAst(node.condition, resolve, invocation),
        body: substituteAst(node.body, resolve, invocation),
      };
    case "RepeatExpression":
      return { ...node, body: substituteAst(node.body, resolve, invocation) };
    case "ReturnExpression":
      return node.value === undefined
        ? node
        : { ...node, value: substituteAst(node.value, resolve, invocation) };
    case "SubsetExpression":
      return {
        ...node,
        target: substituteAst(node.target, resolve, invocation),
        arguments: substituteCallArguments(node.arguments, resolve, invocation),
      };
    case "NamespaceExpression":
      return {
        ...node,
        namespace: substituteAst(node.namespace, resolve, invocation),
        member: substituteAst(node.member, resolve, invocation),
      };
    case "FormulaExpression":
      return {
        ...node,
        ...(node.left === undefined ? {} : { left: substituteAst(node.left, resolve, invocation) }),
        right: substituteAst(node.right, resolve, invocation),
      };
    case "PipeExpression":
      return {
        ...node,
        left: substituteAst(node.left, resolve, invocation),
        right: substituteAst(node.right, resolve, invocation),
      };
    case "UnsupportedExpression":
      return node.feature === "dots"
        ? substituteIdentifier({ kind: "Identifier", name: "...", span: node.span }, resolve)
        : node;
    case "ConstantExpression":
      return node;
    default:
      return assertNever(node);
  }
}

function substituteCallArguments(
  arguments_: readonly CallArgument[],
  resolve: (name: string) => RBinding | undefined,
  invocation: BuiltinInvocation,
): readonly CallArgument[] {
  const result: CallArgument[] = [];
  for (const argument of arguments_) {
    if (isDotsAst(argument.value)) {
      const dots = resolve("...");
      if (dots?.type === "dots") {
        for (const entry of dots.arguments) {
          const value = promiseAst(entry.promise);
          result.push({
            ...(entry.name === undefined ? {} : { name: entry.name }),
            value,
            span: value.span,
          });
        }
        continue;
      }
    }
    const value = substituteAst(argument.value, resolve, invocation);
    result.push({
      ...(argument.name === undefined ? {} : { name: argument.name }),
      value,
      span: value.span,
    });
  }
  return result;
}

function substituteIdentifier(
  node: Extract<AstNode, { readonly kind: "Identifier" }>,
  resolve: (name: string) => RBinding | undefined,
): AstNode {
  const binding = resolve(node.name);
  if (binding === undefined) return node;
  if (binding.type === "dots") {
    const first = binding.arguments[0];
    return first === undefined ? nullAst() : promiseAst(first.promise);
  }
  if (binding.type === "active-binding") {
    throw new RUnsupportedFeatureError(
      "NRU6222",
      "substitute() over an active binding is not implemented yet.",
    );
  }
  if (binding.type === "promise") return promiseAst(binding);
  return embeddedCallArgumentAst(binding);
}

function promiseAst(promise: RBinding & { readonly type: "promise" }): AstNode {
  if (promise.expression !== null) return promise.expression;
  if (promise.value !== undefined) return embeddedCallArgumentAst(promise.value);
  return {
    kind: "UnsupportedExpression",
    feature: "missing argument",
    span: SYNTHETIC_SPAN,
  };
}

function isDotsAst(node: AstNode): boolean {
  return (
    (node.kind === "Identifier" && node.name === "...") ||
    (node.kind === "UnsupportedExpression" && node.feature === "dots")
  );
}

async function builtinMatchCall(invocation: BuiltinInvocation): Promise<RLanguage> {
  const matched = matchLazyArguments(invocation, ["definition", "call", "expand.dots", "envir"]);
  const definitionArgument = matched.get("definition");
  const definitionValue =
    definitionArgument === undefined
      ? undefined
      : await invocation.force(definitionArgument.promise);
  if (
    definitionValue !== undefined &&
    definitionValue.type !== "closure" &&
    definitionValue.type !== "builtin"
  ) {
    throw new RTypeMismatchError("NRT3214", "invalid 'definition' argument");
  }
  const callArgument = matched.get("call");
  const callValue =
    callArgument === undefined ? undefined : await invocation.force(callArgument.promise);
  if (callValue !== undefined && callValue.type !== "language") {
    throw new RTypeMismatchError("NRT3214", "invalid 'call' argument");
  }
  const environmentArgument = matched.get("envir");
  if (environmentArgument !== undefined) {
    const environment = await invocation.force(environmentArgument.promise);
    if (environment.type !== "environment") {
      throw new RTypeMismatchError("NRT3214", "invalid 'envir' argument");
    }
  }
  const expandArgument = matched.get("expand.dots");
  const expandDots =
    expandArgument === undefined
      ? true
      : logicalFlag(await invocation.force(expandArgument.promise), true, "expand.dots");
  return invocation.matchCall(expandDots, definitionValue, callValue);
}

async function builtinDoCall(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["what", "args", "quote", "envir"]);
  const what = required(matched, "what", "do.call");
  const args = required(matched, "args", "do.call");
  if (args.type !== "list") {
    throw new RTypeMismatchError("NRT3214", "do.call(args=) requires an ordinary list.");
  }
  const quoteArguments = logicalFlag(matched.get("quote"), false, "quote");
  const environment = matched.get("envir") ?? invocation.currentEnvironment();
  if (environment.type !== "environment") {
    throw new RTypeMismatchError("NRT3214", "do.call(envir=) requires an environment.");
  }

  let callable = what;
  if (what.type === "character") {
    const name = characterScalar(what, "what");
    let current: REnvironment | null = environment;
    let resolved: RValue | undefined;
    while (current !== null) {
      const binding = current.bindings.get(name);
      if (binding !== undefined && binding.type !== "dots") {
        const candidate = await invocation.force(binding);
        if (candidate.type === "closure" || candidate.type === "builtin") {
          resolved = candidate;
          break;
        }
      }
      current = current.parent;
    }
    if (resolved === undefined) {
      throw new REvaluationError("NRE2001", `Could not find function '${name}'.`);
    }
    callable = resolved;
  }
  if (callable.type !== "closure" && callable.type !== "builtin") {
    throw new RTypeMismatchError(
      "NRT3214",
      "do.call(what=) requires a function or one function name.",
    );
  }

  const names = vectorNames(args);
  return invocation.invokeLazy(
    callable,
    args.values.map((value, index) => {
      const name = names?.[index];
      const valueAst = languageValueAst(value);
      const expression = quoteArguments
        ? ({
            kind: "CallExpression",
            callee: {
              kind: "NamespaceExpression",
              operator: "::",
              namespace: { kind: "Identifier", name: "base", span: SYNTHETIC_SPAN },
              member: { kind: "Identifier", name: "quote", span: SYNTHETIC_SPAN },
              span: SYNTHETIC_SPAN,
            },
            arguments: [{ value: valueAst, span: SYNTHETIC_SPAN }],
            span: SYNTHETIC_SPAN,
          } satisfies AstNode)
        : valueAst;
      const missing =
        !quoteArguments &&
        expression.kind === "UnsupportedExpression" &&
        expression.feature === "missing argument";
      const argument = {
        promise: missing
          ? createMissingPromise(environment)
          : createPromise(expression, environment),
        span: SYNTHETIC_SPAN,
      };
      return name === undefined || name === "" ? argument : { ...argument, name };
    }),
  );
}

async function builtinForce(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["x"]);
  const argument = matched.get("x");
  if (argument === undefined) {
    throw new REvaluationError("NRE2103", "Argument 'x' is missing in force().");
  }
  return invocation.force(argument.promise);
}

async function builtinInterruptControl(
  invocation: BuiltinInvocation,
  mode: "suspend" | "allow",
): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["expr"]);
  const argument = matched.get("expr");
  if (argument === undefined || argument.promise.missing) {
    throw new REvaluationError("NRE2103", 'Argument "expr" is missing, with no default.');
  }
  invocation.context.pushInterruptMode(mode);
  let result: Awaited<ReturnType<BuiltinInvocation["forceDetailed"]>>;
  try {
    result = await invocation.forceDetailed(argument.promise);
  } finally {
    invocation.context.popInterruptMode();
  }
  invocation.context.checkpoint(0);
  invocation.setResultVisibility(result.visible ? "visible" : "invisible");
  return result.value;
}

async function builtinIdentity(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["x"]);
  const argument = matched.get("x");
  if (argument === undefined) {
    throw new REvaluationError("NRE2103", "Argument 'x' is missing in identity().");
  }
  return invocation.force(argument.promise);
}

async function builtinAsIs(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["x"]);
  const input = required(matched, "x", "I");
  if (!isAttributedSequence(input) && input.type !== "expression") {
    throw new RTypeMismatchError(
      "NRT3230",
      input.type === "null"
        ? "attempt to set an attribute on NULL"
        : `attempt to set an attribute on a value of type '${input.type}'`,
    );
  }
  const classes = objectClasses(input) ?? [];
  const replacement = characterVector([
    "AsIs",
    ...classes.filter((className) => className !== "AsIs"),
  ]);
  return isAttributedSequence(input)
    ? withClasses(input, replacement.values)
    : replaceRuntimeAttribute(input, "class", replacement);
}

async function builtinNoQuote(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["obj", "right"]);
  const input = required(matched, "obj", "noquote");
  if (!isAttributedRuntimeObject(input)) {
    throw new RTypeMismatchError(
      "NRT3230",
      input.type === "null"
        ? "attempt to set an attribute on NULL"
        : `attempt to set an attribute on a value of type '${input.type}'`,
    );
  }
  const classes = objectClasses(input) ?? [];
  if (classes.includes("noquote")) return input;
  const rightValue = matched.get("right");
  const right = findMatchesLogicalControl(rightValue, false, "right");
  let replacement = characterVector([...classes, "noquote"]);
  if (right) {
    replacement = withNames(replacement, [...classes.map(() => ""), "right"]);
  }
  return replaceRuntimeAttribute(input, "class", replacement);
}

async function builtinSymbolicNumber(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, [
    "x",
    "cutpoints",
    "symbols",
    "legend",
    "na",
    "eps",
    "numeric.x",
    "corr",
    "show.max",
    "show.min",
    "abbr.colnames",
    "lower.triangular",
    "diag.lower.tri",
  ]);
  const input = required(matched, "x", "symnum");
  if (!isAtomic(input)) {
    throw new RTypeMismatchError("NRT3491", "'x' must be numeric or logical");
  }

  const inputIsNumeric =
    input.type === "integer" || input.type === "double" || input.type === "complex";
  const numericX = logicalFlag(matched.get("numeric.x"), inputIsNumeric, "numeric.x");
  const cutpointsWereMissing = !matched.has("cutpoints");
  const correlation = logicalFlag(matched.get("corr"), cutpointsWereMissing && numericX, "corr");
  if (numericX && !inputIsNumeric) {
    throw new RTypeMismatchError("NRT3491", "'x' must be numeric");
  }
  if (numericX && input.type === "complex") {
    throw new RTypeMismatchError("NRT3491", "invalid subscript type 'complex'");
  }

  const defaultSymbols = numericX ? [" ", ".", ",", "+", "*", "B"] : [".", "|"];
  const symbolsValue = matched.get("symbols") ?? characterVector(defaultSymbols);
  if (symbolsValue.type !== "character") {
    throw new RTypeMismatchError("NRT3491", "'symbols' must be a character vector");
  }
  const symbols = symbolsValue.values;
  if (!numericX && symbolsValue.length !== 2) {
    throw new REvaluationError("NRE2260", "must have 2 'symbols' for logical 'x' argument");
  }

  let cutpoints = numericX
    ? symbolicNumberCutpoints(matched.get("cutpoints") ?? doubleVector([0.3, 0.6, 0.8, 0.9, 0.95]))
    : [];
  if (correlation && numericX) {
    cutpoints = symbolicNumberSortedUnique([0, ...cutpoints, 1]);
  }
  if (numericX && cutpoints.length !== symbolsValue.length + 1) {
    throw new REvaluationError(
      "NRE2260",
      "number of 'cutpoints' must be one more than number of symbols",
    );
  }

  const eps = numericScalar(matched.get("eps") ?? doubleVector([1e-5]), "eps");
  const showMaximum = matched.has("show.max")
    ? matched.get("show.max")
    : correlation
      ? characterVector(["1"])
      : R_NULL;
  const showMinimum = matched.get("show.min") ?? R_NULL;
  const dimensions = vectorDimensions(input);
  const matrix = dimensions !== undefined && dimensions.length === 2;
  const columnNames = symbolicNumberColumnNames(input);
  const hasColumnNames = columnNames !== undefined;
  const abbreviateColumns = matched.get("abbr.colnames");
  const lowerTriangular = logicalFlag(
    matched.get("lower.triangular"),
    correlation && inputIsNumeric && matrix,
    "lower.triangular",
  );
  const diagonalLowerTriangular = logicalFlag(
    matched.get("diag.lower.tri"),
    correlation && showMaximum?.type !== "null",
    "diag.lower.tri",
  );
  const naValue = matched.get("na") ?? characterVector(["?"]);
  if (naValue.type !== "character" && naValue.type !== "logical") {
    throw new RTypeMismatchError("NRT3491", "'na' must be character or logical");
  }

  invocation.context.allocate(input.length);
  const values = Array.from({ length: input.length }, () => "");
  const missing = new Uint8Array(input.length);
  let missingIndex = 0;
  let containsMissing = false;
  const finiteValues: number[] = [];
  if (numericX) {
    for (let index = 0; index < input.length; index += 1) {
      if (isMissing(input, index)) continue;
      const value = numberAt(input, index);
      if (Number.isNaN(value)) continue;
      finiteValues.push(correlation ? Math.abs(value) : value);
    }
    const minimum = cutpoints[0] ?? 0;
    const maximum = cutpoints[cutpoints.length - 1] ?? 0;
    if (finiteValues.some((value) => value < minimum - eps || value > maximum + eps)) {
      throw new REvaluationError(
        "NRE2260",
        `'x' must be between ${formatRNumber(minimum)} and ${formatRNumber(maximum)}`,
      );
    }
  }

  const rows = matrix ? (dimensions?.[0] ?? 0) : 0;
  const columns = matrix ? (dimensions?.[1] ?? 0) : 0;
  for (let index = 0; index < input.length; index += 1) {
    invocation.context.checkpoint();
    const row = rows === 0 ? 0 : index % rows;
    const column = rows === 0 ? 0 : Math.floor(index / rows);
    if (
      lowerTriangular &&
      matrix &&
      column < columns &&
      (row < column || (!diagonalLowerTriangular && row === column))
    ) {
      values[index] = "";
      continue;
    }
    const sourceMissing =
      isMissing(input, index) ||
      (numericX && input.type !== "complex" && Number.isNaN(numberAt(input, index)));
    if (sourceMissing) {
      containsMissing = true;
      if (naValue.type === "logical" || naValue.length === 0) {
        values[index] = "";
      } else {
        const replacement = missingIndex % naValue.length;
        if (isMissing(naValue, replacement)) missing[index] = 1;
        else values[index] = naValue.values[replacement] ?? "";
        missingIndex += 1;
      }
      continue;
    }
    if (!numericX) {
      if (input.type !== "logical") {
        throw new RTypeMismatchError("NRT3491", "'x' must be logical when 'numeric.x' is false");
      }
      const symbolIndex = input.values[index] === 1 ? 1 : 0;
      values[index] = symbols[symbolIndex] ?? "";
      if (isMissing(symbolsValue, symbolIndex)) missing[index] = 1;
      continue;
    }

    const raw = numberAt(input, index);
    const value = correlation ? Math.abs(raw) : raw;
    const minimum = cutpoints[0] ?? 0;
    const maximum = cutpoints[cutpoints.length - 1] ?? 0;
    const minimumDisplay = symbolicNumberEndpoint(showMinimum, minimum);
    const maximumDisplay = symbolicNumberEndpoint(showMaximum, maximum);
    if (minimumDisplay !== undefined && value <= minimum + eps) {
      values[index] = minimumDisplay.value;
      if (minimumDisplay.missing) missing[index] = 1;
      continue;
    }
    if (maximumDisplay !== undefined && value >= maximum - eps) {
      values[index] = maximumDisplay.value;
      if (maximumDisplay.missing) missing[index] = 1;
      continue;
    }
    const symbolIndex = symbolicNumberInterval(value, cutpoints);
    values[index] = symbols[symbolIndex] ?? "";
    if (isMissing(symbolsValue, symbolIndex)) missing[index] = 1;
  }

  let result = characterVector(values, compactMask(missing));
  for (const [name, attribute] of input.attributes) {
    if (name !== "class" && name !== "dimnames") result = withAttribute(result, name, attribute);
  }
  const dimnames = symbolicNumberDimnames(input, abbreviateColumns, hasColumnNames, invocation);
  if (dimnames !== undefined) result = withAttribute(result, "dimnames", dimnames);
  const legend = logicalFlag(matched.get("legend"), symbolsValue.length >= 3, "legend");
  if (legend) {
    result = withAttribute(
      result,
      "legend",
      characterVector([symbolicNumberLegend(cutpoints, symbolsValue, naValue, containsMissing)]),
    );
  }
  return withClasses(result, ["noquote"]);
}

function symbolicNumberCutpoints(value: RValue): number[] {
  if (value.type !== "integer" && value.type !== "double") {
    throw new RTypeMismatchError("NRT3491", "'cutpoints' must be numeric");
  }
  const values: number[] = [];
  for (let index = 0; index < value.length; index += 1) {
    if (isMissing(value, index)) continue;
    const point = value.values[index] ?? 0;
    if (!Number.isNaN(point)) values.push(point);
  }
  return symbolicNumberSortedUnique(values);
}

function symbolicNumberSortedUnique(values: readonly number[]): number[] {
  return [...new Set(values)].sort((left, right) => left - right);
}

function symbolicNumberInterval(value: number, cutpoints: readonly number[]): number {
  for (let index = 1; index < cutpoints.length; index += 1) {
    if (value <= (cutpoints[index] ?? Number.POSITIVE_INFINITY)) return index - 1;
  }
  return Math.max(0, cutpoints.length - 2);
}

function symbolicNumberEndpoint(
  value: RValue | undefined,
  cutpoint: number,
): { readonly value: string; readonly missing: boolean } | undefined {
  if (value === undefined || value.type === "null") return undefined;
  if (value.type === "character") {
    if (value.length === 0) return { value: formatRNumber(cutpoint), missing: false };
    return {
      value: value.values[0] ?? "",
      missing: isMissing(value, 0),
    };
  }
  return { value: formatRNumber(cutpoint), missing: false };
}

function symbolicNumberColumnNames(input: AtomicVector): RCharacterVector | undefined {
  const dimnames = input.attributes.get("dimnames");
  if (dimnames?.type !== "list" || dimnames.values.length < 2) return undefined;
  const columns = dimnames.values[1];
  return columns?.type === "character" ? columns : undefined;
}

function symbolicNumberDimnames(
  input: AtomicVector,
  requested: RValue | undefined,
  hasColumnNames: boolean,
  invocation: BuiltinInvocation,
): RList | undefined {
  const dimensions = vectorDimensions(input);
  if (dimensions === undefined || dimensions.length < 2) return undefined;
  const original = input.attributes.get("dimnames");
  const entries =
    original?.type === "list"
      ? [...original.values]
      : Array.from({ length: dimensions.length }, () => R_NULL as RValue);
  while (entries.length < dimensions.length) entries.push(R_NULL);
  const columnCount = dimensions[1] ?? 0;
  const columns = symbolicNumberColumnNames(input);
  if (requested === undefined) {
    if (hasColumnNames && columns !== undefined) {
      entries[1] = symbolicNumberAbbreviatedColumns(columns, 4, invocation);
    } else {
      entries[1] = characterVector(Array.from({ length: columnCount }, () => ""));
    }
  } else if (requested.type === "null") {
    entries[1] = characterVector(Array.from({ length: columnCount }, () => ""));
  } else {
    const enabled = logicalFlag(requested, false, "abbr.colnames");
    if (enabled && columns !== undefined) {
      const minimum =
        requested.type === "integer" || requested.type === "double"
          ? Math.trunc(requested.values[0] ?? 4)
          : 4;
      if (minimum < 1) throw new REvaluationError("NRE2260", "invalid 'abbr.colnames'");
      entries[1] = symbolicNumberAbbreviatedColumns(columns, minimum, invocation);
    } else if (!enabled) {
      entries[1] = columns ?? characterVector(Array.from({ length: columnCount }, () => ""));
    }
  }
  let result = listValue(entries);
  if (original?.type === "list") {
    for (const [name, attribute] of original.attributes)
      result = withAttribute(result, name, attribute);
  }
  return result;
}

function symbolicNumberAbbreviatedColumns(
  columns: RCharacterVector,
  minimum: number,
  invocation: BuiltinInvocation,
): RCharacterVector {
  invocation.context.allocate(columns.length);
  const targets = columns.values.map(() => minimum);
  const values = columns.values.map((value, index) =>
    isMissing(columns, index)
      ? ""
      : abbreviateString(value, minimum, true, false, false, "left.kept"),
  );
  for (;;) {
    const groups = new Map<string, number[]>();
    for (let index = 0; index < values.length; index += 1) {
      if (isMissing(columns, index)) continue;
      const value = values[index] ?? "";
      const group = groups.get(value) ?? [];
      group.push(index);
      groups.set(value, group);
    }
    let changed = false;
    for (const group of groups.values()) {
      if (group.length < 2) continue;
      for (const index of group) {
        const source = columns.values[index] ?? "";
        if ((targets[index] ?? minimum) >= [...source].length) continue;
        targets[index] = (targets[index] ?? minimum) + 1;
        values[index] = abbreviateString(
          source,
          targets[index] ?? minimum,
          true,
          false,
          false,
          "left.kept",
        );
        changed = true;
      }
    }
    if (!changed) break;
  }
  for (let index = 0; index < columns.length; index += 1) invocation.context.checkpoint();
  return withNames(
    characterVector(values, columns.missing),
    columns.values.map((value, index) => (isMissing(columns, index) ? "" : value)),
  );
}

function symbolicNumberLegend(
  cutpoints: readonly number[],
  symbols: RCharacterVector,
  na: RCharacterVector | RLogicalVector,
  containsMissing: boolean,
): string {
  const pieces: string[] = [];
  for (let index = 0; index < cutpoints.length; index += 1) {
    pieces.push(formatRNumber(cutpoints[index] ?? 0));
    if (index < symbols.length) {
      pieces.push(`'${isMissing(symbols, index) ? "NA" : (symbols.values[index] ?? "")}'`);
    }
  }
  if (containsMissing && na.type === "character") {
    for (let index = 0; index < na.length; index += 1) {
      pieces.push(`\t    ## NA: '${isMissing(na, index) ? "NA" : (na.values[index] ?? "")}'`);
    }
  }
  return pieces.join(" ");
}

async function builtinOnExit(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["expr", "add", "after"]);
  const addArgument = matched.get("add");
  const afterArgument = matched.get("after");
  const add =
    addArgument === undefined
      ? false
      : logicalFlag(await invocation.force(addArgument.promise), false, "add");
  const after =
    afterArgument === undefined
      ? true
      : logicalFlag(await invocation.force(afterArgument.promise), true, "after");
  const expressionArgument = matched.get("expr");
  invocation.configureOnExit(
    expressionArgument?.promise.missing === false ? expressionArgument.promise.expression : null,
    expressionArgument?.promise.environment ?? invocation.currentEnvironment(),
    add,
    after,
  );
  return R_NULL;
}

async function builtinInvisible(invocation: BuiltinInvocation): Promise<RValue> {
  if (invocation.arguments.length > 1) {
    throw new REvaluationError("NRE2101", "Unused argument in invisible().");
  }
  const argument = invocation.arguments[0];
  return argument === undefined ? R_NULL : invocation.force(argument.promise);
}

async function builtinWithVisible(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["x"]);
  const argument = matched.get("x");
  if (argument === undefined || argument.promise.missing) {
    throw new REvaluationError("NRE2103", "Argument 'x' is missing in withVisible().");
  }
  const result = await invocation.forceDetailed(argument.promise);
  invocation.context.allocate(3);
  return listValue([result.value, logicalVector([result.visible])], ["value", "visible"]);
}

async function builtinWithAutoprint(invocation: BuiltinInvocation): Promise<RValue> {
  const { matched } = matchBuiltinArguments(invocation, [
    "exprs",
    "evaluated",
    "local",
    "print.",
    "echo",
    "max.deparse.length",
    "width.cutoff",
    "deparseCtrl",
    "skip.echo",
    "...",
  ]);
  const expressionArgument = matched.get("exprs");
  if (expressionArgument === undefined || expressionArgument.promise.missing) {
    throw new REvaluationError("NRE2103", "Argument 'exprs' is missing in withAutoprint().");
  }
  const evaluatedArgument = matched.get("evaluated");
  const evaluated =
    evaluatedArgument === undefined || evaluatedArgument.promise.missing
      ? false
      : logicalFlag(await invocation.force(evaluatedArgument.promise), false, "evaluated");
  let nodes: readonly AstNode[];
  if (evaluated) {
    nodes = sourceExpressionNodes(await invocation.force(expressionArgument.promise));
  } else {
    const expression = expressionArgument.promise.expression;
    if (expression === null) {
      throw new REvaluationError("NRE2103", "Argument 'exprs' is missing in withAutoprint().");
    }
    nodes = expression.kind === "Block" ? expression.body : [expression];
  }
  const localArgument = matched.get("local");
  const environment =
    localArgument === undefined || localArgument.promise.missing
      ? expressionArgument.promise.environment
      : await invocation.force(localArgument.promise);
  if (environment.type !== "environment") {
    throw new RTypeMismatchError("NRT3409", "withAutoprint(local=) must be an environment.");
  }
  const flag = async (name: "print." | "echo", fallback: boolean): Promise<boolean> => {
    const argument = matched.get(name);
    return argument === undefined || argument.promise.missing
      ? fallback
      : logicalFlag(await invocation.force(argument.promise), fallback, name);
  };
  const printEvaluation = await flag("print.", true);
  const echo = await flag("echo", true);
  const maxDeparseArgument = matched.get("max.deparse.length");
  const maxDeparseLength =
    maxDeparseArgument === undefined || maxDeparseArgument.promise.missing
      ? Number.POSITIVE_INFINITY
      : numericScalar(await invocation.force(maxDeparseArgument.promise), "max.deparse.length");
  const skipArgument = matched.get("skip.echo");
  const skipEcho =
    skipArgument === undefined || skipArgument.promise.missing
      ? 0
      : nonNegativeInteger(await invocation.force(skipArgument.promise), "skip.echo");
  for (const name of ["width.cutoff", "deparseCtrl"] as const) {
    const argument = matched.get(name);
    if (argument !== undefined && !argument.promise.missing)
      await invocation.force(argument.promise);
  }
  let lastValue: RValue = R_NULL;
  let lastVisible = false;
  const print = printEvaluation ? await lookupCallableByName(invocation, "print") : undefined;
  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index]!;
    invocation.context.checkpoint();
    if (echo && index >= skipEcho) {
      const deparsed = deparseAst(node);
      const displayed =
        deparsed.length <= maxDeparseLength
          ? deparsed
          : `${deparsed.slice(0, Math.max(0, maxDeparseLength))} .... [TRUNCATED] `;
      invocation.context.writeOutput({ stream: "stdout", text: `> ${displayed}\n` });
    }
    const result = await invocation.evaluateDetailed(
      { type: "language", expression: node },
      environment,
    );
    lastValue = result.value;
    lastVisible = result.visible;
    if (print !== undefined && result.visible) {
      await invocation.invoke(print, [{ value: result.value }]);
    }
  }
  invocation.context.allocate(2);
  invocation.setResultVisibility("invisible");
  return listValue([lastValue, logicalVector([lastVisible])], ["value", "visible"]);
}

async function builtinOptions(invocation: BuiltinInvocation): Promise<RValue> {
  const state = optionsState(invocation);
  if (invocation.arguments.length === 0) {
    const entries = [...state].sort(([left], [right]) => left.localeCompare(right));
    invocation.context.allocate(entries.length);
    return listValue(
      entries.map(([, value]) => value),
      entries.map(([name]) => name),
    );
  }

  const values: RValue[] = [];
  const names: string[] = [];
  let changed = false;
  for (const argument of invocation.arguments) {
    const value = await invocation.force(argument.promise);
    if (argument.name !== undefined) {
      applyOption(argument.name, value, state, values, names);
      changed = true;
      continue;
    }
    if (value.type === "character") {
      for (let index = 0; index < value.length; index += 1) {
        if (isMissing(value, index)) {
          throw new RTypeMismatchError("NRT3222", "Option names cannot be missing.");
        }
        const name = value.values[index] ?? "";
        validateOptionName(name);
        names.push(name);
        values.push(state.get(name) ?? R_NULL);
      }
      continue;
    }
    if (value.type === "list") {
      const listNames = vectorNames(value);
      if (
        (value.length > 0 && listNames === undefined) ||
        listNames?.some((name) => name.length === 0)
      ) {
        throw new RTypeMismatchError("NRT3222", "An options() list must have non-empty names.");
      }
      for (let index = 0; index < value.length; index += 1) {
        applyOption(listNames?.[index] ?? "", value.values[index] ?? R_NULL, state, values, names);
      }
      changed = true;
      continue;
    }
    throw new RTypeMismatchError(
      "NRT3222",
      "Unnamed options() arguments must be character names or a named list.",
    );
  }
  invocation.context.allocate(values.length);
  if (changed) {
    syncInvocationOptionsBindings(invocation, state);
    invocation.setResultVisibility("invisible");
  }
  return listValue(values, names);
}

async function builtinGetOption(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = matchLazyArguments(invocation, ["x", "default"]);
  const nameArgument = matched.get("x");
  if (nameArgument === undefined) {
    throw new REvaluationError("NRE2103", "Argument 'x' is missing in getOption().");
  }
  const name = characterScalar(await invocation.force(nameArgument.promise), "x");
  const stored = optionsState(invocation).get(name);
  if (stored !== undefined) return stored;
  const fallback = matched.get("default");
  return fallback === undefined ? R_NULL : invocation.force(fallback.promise);
}

async function builtinInteractive(invocation: BuiltinInvocation): Promise<RValue> {
  await matchExact(invocation, []);
  return logicalVector([invocation.isInteractive()]);
}

async function builtinCommandArgs(invocation: BuiltinInvocation): Promise<RCharacterVector> {
  const matched = await matchExact(invocation, ["trailingOnly"]);
  const trailingOnly = logicalFlag(matched.get("trailingOnly"), false, "trailingOnly");
  return characterVector(trailingOnly ? [] : ["nativr"]);
}

async function builtinReadline(invocation: BuiltinInvocation): Promise<RCharacterVector> {
  const matched = await matchExact(invocation, ["prompt"]);
  const prompt = readlinePrompt(matched.get("prompt"));
  const displayedPrompt = Array.from(prompt).slice(0, 256).join("");
  if (displayedPrompt.length > 0 || !invocation.isInteractive()) {
    invocation.context.writeOutput({
      stream: "stdout",
      text: `${displayedPrompt}${invocation.isInteractive() ? "" : "\n"}`,
    });
  }
  const response = await invocation.readline(displayedPrompt);
  invocation.context.allocate(1);
  return characterVector([response.replace(/^[ \t]+|[ \t]+$/gu, "")]);
}

function readlinePrompt(value: RValue | undefined): string {
  if (value === undefined || value.type === "null" || (isVector(value) && value.length === 0)) {
    return "";
  }
  if (!isAtomic(value)) {
    throw new RTypeMismatchError("NRT3410", "readline(prompt=) must be coercible to character.");
  }
  if (isMissing(value, 0)) return "NA";
  if (isFactor(value)) return factorLevels(value)[(value.values[0] ?? 0) - 1] ?? "";
  return stringAt(value, 0);
}

function builtinSystemGetPid(invocation: BuiltinInvocation): RIntegerVector {
  if (invocation.arguments.length > 0) {
    throw new REvaluationError("NRE2101", "Sys.getpid() does not accept arguments.");
  }
  invocation.context.allocate(1);
  return integerVector([invocation.sessionProcessId]);
}

function builtinSystemInfo(invocation: BuiltinInvocation): RCharacterVector {
  if (invocation.arguments.length > 0) {
    throw new REvaluationError("NRE2101", "Sys.info() does not accept arguments.");
  }
  const names = [
    "sysname",
    "release",
    "version",
    "nodename",
    "machine",
    "login",
    "user",
    "effective_user",
  ];
  invocation.context.allocate(names.length);
  return withNames(
    characterVector([
      "NativR",
      "browser",
      "GNU R 4.6.1-compatible NativR runtime",
      "browser",
      "wasm32",
      "nativr",
      "nativr",
      "nativr",
    ]),
    names,
  );
}

const BROWSER_CAPABILITY_NAMES = Object.freeze([
  "jpeg",
  "png",
  "tiff",
  "tcltk",
  "X11",
  "aqua",
  "http/ftp",
  "sockets",
  "libxml",
  "fifo",
  "cledit",
  "iconv",
  "NLS",
  "Rprof",
  "profmem",
  "cairo",
  "ICU",
  "long.double",
  "libcurl",
] as const);

async function builtinCapabilities(invocation: BuiltinInvocation): Promise<RLogicalVector> {
  const matched = matchLazyArguments(invocation, ["what", "Xchk"]);
  const whatArgument = matched.get("what");
  const requested =
    whatArgument === undefined ? undefined : await invocation.force(whatArgument.promise);
  const names =
    requested === undefined || requested.type === "null"
      ? [...BROWSER_CAPABILITY_NAMES]
      : capabilitySelection(requested);
  invocation.context.allocate(names.length);
  return withNames(
    logicalVector(
      names.map(
        (name) => name === "png" || (name === "sockets" && invocation.hasSocketCapability()),
      ),
    ),
    names,
  );
}

async function builtinGcTorture2(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["step", "wait", "inhibit_release"]);
  const step = nonNegativeInteger(matched.get("step"), "step");
  const wait = nonNegativeInteger(matched.get("wait") ?? integerVector([step]), "wait");
  const inhibitRelease = logicalFlag(matched.get("inhibit_release"), false, "inhibit_release");
  const previous = invocation.state.get(GC_TORTURE_STATE_KEY);
  invocation.state.set(GC_TORTURE_STATE_KEY, { step, wait, inhibitRelease });
  return integerVector([
    typeof previous === "object" && previous !== null && "step" in previous
      ? Number(previous.step)
      : 0,
  ]);
}

async function builtinPackageEvent(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["pkgname", "event"]);
  const packageName = characterScalar(required(matched, "pkgname", "packageEvent"), "pkgname");
  const event = characterScalar(required(matched, "event", "packageEvent"), "event");
  if (!new Set(["onLoad", "attach", "detach", "onUnload"]).has(event)) {
    throw new RTypeMismatchError(
      "NRT3395",
      `'arg' should be one of “onLoad”, “attach”, “detach”, “onUnload”`,
    );
  }
  return characterVector([`UserHook::${packageName}::${event}`]);
}

function hooksState(invocation: BuiltinInvocation): Map<string, RValue[]> {
  return stateMap<string, RValue[]>(invocation, HOOKS_STATE_KEY);
}

async function builtinGetHook(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["hookName"]);
  const name = characterScalar(required(matched, "hookName", "getHook"), "hookName");
  const values = hooksState(invocation).get(name) ?? [];
  invocation.context.allocate(values.length);
  return listValue(values);
}

async function builtinSetHook(invocation: BuiltinInvocation): Promise<RValue> {
  const matched = await matchExact(invocation, ["hookName", "value", "action"]);
  const name = characterScalar(required(matched, "hookName", "setHook"), "hookName");
  const value = required(matched, "value", "setHook");
  const values =
    value.type === "null"
      ? []
      : value.type === "list" || value.type === "pairlist"
        ? [...value.values]
        : [value];
  const suppliedAction = matched.get("action");
  const requestedAction =
    suppliedAction === undefined
      ? "append"
      : suppliedAction.type === "character" &&
          suppliedAction.length > 0 &&
          !isMissing(suppliedAction, 0)
        ? (suppliedAction.values[0] ?? "")
        : "";
  const actions = ["append", "prepend", "replace"] as const;
  const action =
    actions.find((candidate) => candidate === requestedAction) ??
    actions
      .filter((candidate) => requestedAction.length > 0 && candidate.startsWith(requestedAction))
      .at(0);
  if (
    action === undefined ||
    actions.filter((candidate) => candidate.startsWith(requestedAction)).length !== 1
  ) {
    throw new RTypeMismatchError(
      "NRT3397",
      `'arg' should be one of “append”, “prepend”, “replace”`,
    );
  }
  const hooks = hooksState(invocation);
  const existing = hooks.get(name) ?? [];
  hooks.set(
    name,
    action === "replace"
      ? values
      : action === "prepend"
        ? [...values, ...existing]
        : [...existing, ...values],
  );
  return R_NULL;
}

function capabilitySelection(value: RValue): string[] {
  const candidates: string[] = [];
  if (isAtomic(value)) {
    for (let index = 0; index < value.length; index += 1) {
      if (isMissing(value, index)) continue;
      const name = isFactor(value)
        ? (factorLevels(value)[(value.values[index] ?? 0) - 1] ?? "")
        : stringAt(value, index);
      candidates.push(name);
    }
  } else if (value.type === "list" || value.type === "pairlist") {
    for (const entry of value.values) {
      candidates.push(...capabilitySelection(entry));
    }
  }
  const available = new Set<string>(BROWSER_CAPABILITY_NAMES);
  return candidates.filter((name) => available.has(name));
}

