  const retained = removed === 0 ? observed : observed.slice(removed, observed.length - removed);
  const total = retained.reduce((sum, item) => sum + item.real, 0);
  const imaginaryTotal = retained.reduce((sum, item) => sum + item.imaginary, 0);
  const count = retained.length;
  invocation.context.allocate(1);
